def count_vowels(s):
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    # Using set for unique vowel lookup; list comprehension for dynamic list creation
    vowels = set('aeiouAEIOU')

    # If grade is missing, it should return 0 as there are no vowels
    return sum(1 for char in s if char in vowels)

# Example usage:
